-- 006_employee_onboarding.sql — administrator-managed onboarding.
--  * One-time passwords are generated by the server (Edge Function) and expire after 72 hours.
--    Until the employee replaces it, the temporary password only allows changing the password:
--    every business write is refused (require_actor(true)) and the UI shows only the change screen.
--  * The administrator can assign work (tasks) like a supervisor.

ALTER TABLE factory.employees ADD COLUMN temp_password_expires_at timestamptz;

/** Resolves the caller from the verified JWT (auth.uid()). Never trusts client input. */
CREATE OR REPLACE FUNCTION factory.require_actor(p_write boolean) RETURNS factory.actor_t
LANGUAGE plpgsql STABLE SET search_path = '' AS $$
DECLARE
  a factory.actor_t;
  v_uid uuid := auth.uid();
  v_expired boolean;
BEGIN
  IF v_uid IS NULL THEN PERFORM factory.err('UNAUTHENTICATED', 'يجب تسجيل الدخول'); END IF;
  SELECT e.id, e.username, e.display_name, e.must_change_password,
         e.must_change_password AND e.temp_password_expires_at IS NOT NULL AND e.temp_password_expires_at < now()
    INTO a.employee_id, a.username, a.display_name, a.must_change, v_expired
    FROM factory.employees e WHERE e.auth_user_id = v_uid AND e.active;
  IF a.employee_id IS NULL THEN PERFORM factory.err('UNAUTHENTICATED', 'الحساب غير مرتبط بموظف فعّال'); END IF;
  IF v_expired THEN
    PERFORM factory.err('UNAUTHENTICATED', 'انتهت صلاحية كلمة المرور المؤقتة (72 ساعة). اطلب من مدير النظام إصدار كلمة جديدة.');
  END IF;
  IF p_write AND a.must_change THEN
    PERFORM factory.err('PASSWORD_CHANGE_REQUIRED', 'يجب تغيير كلمة المرور المؤقتة أولاً من صفحة «حسابي»');
  END IF;
  SELECT coalesce(array_agg(DISTINCT r.role::text) FILTER (WHERE r.role <> 'WORKER'), '{}'),
         coalesce(array_agg(DISTINCT d.id) FILTER (WHERE r.role = 'WORKER' AND d.active), '{}'),
         coalesce(array_agg(DISTINCT d.stage::text) FILTER (WHERE r.role = 'WORKER' AND d.active AND d.stage IS NOT NULL), '{}')
    INTO a.roles, a.dept_ids, a.stages
    FROM factory.employee_roles r LEFT JOIN factory.departments d ON d.id = r.department_id
   WHERE r.employee_id = a.employee_id AND r.active;
  RETURN a;
END $$;

-- ---------------------------------------------------------------- service functions (Edge Functions only)
CREATE OR REPLACE FUNCTION public.svc_provision_employee(p_caller uuid, p_auth_user uuid, p_username text, p_display text, p_roles jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_admin uuid; v_id uuid; v_user text := lower(btrim(p_username)); v_name text := btrim(p_display);
BEGIN
  IF p_caller IS NULL THEN
    IF EXISTS (SELECT 1 FROM factory.employee_roles r JOIN factory.employees e ON e.id = r.employee_id
                WHERE r.role = 'ADMIN' AND r.active AND e.active) THEN
      PERFORM factory.err('FORBIDDEN', 'يوجد مدير نظام بالفعل');
    END IF;
    IF p_roles IS DISTINCT FROM '[{"role": "ADMIN"}]'::jsonb THEN
      PERFORM factory.err('INVALID', 'التهيئة الأولى تنشئ مدير النظام فقط');
    END IF;
  ELSE
    v_admin := factory.require_admin(p_caller);
  END IF;
  IF v_user !~ '^[a-z0-9_.]{3,32}$' THEN PERFORM factory.err('INVALID', 'اسم المستخدم: 3–32 حرفاً لاتينياً صغيراً أو أرقام أو _ .'); END IF;
  IF v_name IS NULL OR length(v_name) NOT BETWEEN 1 AND 100 THEN PERFORM factory.err('INVALID', 'الاسم الظاهر مطلوب'); END IF;
  IF jsonb_typeof(p_roles) <> 'array' OR jsonb_array_length(p_roles) = 0 THEN PERFORM factory.err('INVALID', 'اختر دوراً واحداً على الأقل'); END IF;
  IF EXISTS (SELECT 1 FROM factory.employees WHERE username = v_user) THEN PERFORM factory.err('CONFLICT', 'اسم المستخدم مستخدم مسبقاً'); END IF;
  -- The system generated this password, so it is temporary: must be replaced within 72 hours
  -- (the bootstrap administrator chose their own password).
  INSERT INTO factory.employees (auth_user_id, username, display_name, must_change_password, temp_password_expires_at)
  VALUES (p_auth_user, v_user, v_name, p_caller IS NOT NULL,
          CASE WHEN p_caller IS NOT NULL THEN now() + interval '72 hours' END) RETURNING id INTO v_id;
  PERFORM factory.apply_roles(v_id, p_roles);
  PERFORM factory.audit(v_admin, CASE WHEN p_caller IS NULL THEN 'employee.bootstrap_admin' ELSE 'employee.create' END,
    'employee', v_id::text, NULL, jsonb_build_object('username', v_user, 'displayName', v_name, 'roles', p_roles));
  RETURN jsonb_build_object('id', v_id);
END $$;

/** After the Edge Function set a new one-time password for another employee. */
CREATE OR REPLACE FUNCTION public.svc_after_password_reset(p_caller uuid, p_employee uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_admin uuid := factory.require_admin(p_caller);
BEGIN
  IF p_employee = v_admin THEN PERFORM factory.err('BUSINESS_RULE', 'لتغيير كلمة مرورك استخدم صفحة «حسابي»'); END IF;
  UPDATE factory.employees SET must_change_password = true, temp_password_expires_at = now() + interval '72 hours', updated_at = now()
   WHERE id = p_employee;
  IF NOT FOUND THEN PERFORM factory.err('NOT_FOUND', 'الموظف غير موجود'); END IF;
  PERFORM factory.audit(v_admin, 'employee.password_reset', 'employee', p_employee::text, NULL, NULL);
  RETURN jsonb_build_object('ok', true);
END $$;

/** Called by the account Edge Function only after it verified the current password and set the new one. */
CREATE OR REPLACE FUNCTION public.svc_password_changed(p_auth_user uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v uuid;
BEGIN
  UPDATE factory.employees SET must_change_password = false, temp_password_expires_at = NULL, updated_at = now()
   WHERE auth_user_id = p_auth_user AND active RETURNING id INTO v;
  IF v IS NULL THEN PERFORM factory.err('NOT_FOUND', 'الحساب غير مرتبط بموظف فعّال'); END IF;
  PERFORM factory.audit(v, 'employee.password_changed', 'employee', v::text, NULL, NULL);
  RETURN jsonb_build_object('ok', true);
END $$;

/** Is this auth user an active employee whose temporary password (if any) has not expired? */
CREATE OR REPLACE FUNCTION public.svc_auth_user_active(p_auth_user uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT EXISTS (SELECT 1 FROM factory.employees WHERE auth_user_id = p_auth_user AND active
                    AND NOT (must_change_password AND temp_password_expires_at IS NOT NULL AND temp_password_expires_at < now()))
$$;

-- ---------------------------------------------------------------- tasks: the administrator may assign work too
CREATE OR REPLACE FUNCTION public.app_create_assignments(p jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  a factory.actor_t := factory.require_actor(true);
  v_line uuid := factory.j_uuid(p, 'orderLineId', true, 'سطر الطلب');
  v_lot uuid := factory.j_uuid(p, 'lotId', false, 'الدفعة');
  v_dept uuid := factory.j_uuid(p, 'departmentId', true, 'القسم');
  v_qty int := factory.j_int(p, 'quantity', 1, 1000000, 'الكمية');
  v_notes text := factory.j_text(p, 'notes', 1, 500, false, 'الملاحظات');
  v_emps uuid[]; v_status text; v_ok int; v_ids uuid[] := '{}'; v_id uuid; e uuid;
BEGIN
  PERFORM factory.assert(factory.has_role(a, 'ADMIN') OR factory.has_role(a, 'SUPERVISOR') OR factory.in_stage(a, 'CUTTING'),
    'توزيع العمل من صلاحية المدير أو المشرف أو قسم القص');
  IF jsonb_typeof(p -> 'employeeIds') IS DISTINCT FROM 'array' OR jsonb_array_length(p -> 'employeeIds') NOT BETWEEN 1 AND 20 THEN
    PERFORM factory.err('INVALID', 'اختر عاملاً واحداً على الأقل');
  END IF;
  -- de-duplicate while keeping the order sent by the client (returned ids follow that order)
  SELECT array_agg(x ORDER BY ord) INTO v_emps FROM (
    SELECT DISTINCT ON (v.x) v.x, v.ord
      FROM (SELECT factory.j_uuid(jsonb_build_object('v', t.elem), 'v', true, 'الموظف') AS x, t.ord AS ord
              FROM jsonb_array_elements_text(p -> 'employeeIds') WITH ORDINALITY AS t(elem, ord)) v
     ORDER BY v.x, v.ord) s;
  SELECT o.status::text INTO v_status FROM factory.order_lines ol JOIN factory.orders o ON o.id = ol.order_id WHERE ol.id = v_line;
  IF v_status IS NULL THEN PERFORM factory.err('NOT_FOUND', 'سطر الطلب غير موجود'); END IF;
  IF v_status <> 'RELEASED' THEN PERFORM factory.err('BUSINESS_RULE', 'يمكن توزيع العمل على الطلبات المطلقة فقط'); END IF;
  IF v_lot IS NOT NULL AND NOT EXISTS (SELECT 1 FROM factory.cut_lots WHERE id = v_lot AND order_line_id = v_line) THEN
    PERFORM factory.err('BUSINESS_RULE', 'الدفعة لا تخص سطر الطلب المحدد');
  END IF;
  SELECT count(*) INTO v_ok FROM factory.employee_roles r JOIN factory.employees em ON em.id = r.employee_id
   WHERE r.department_id = v_dept AND r.role = 'WORKER' AND r.active AND em.active AND r.employee_id = ANY (v_emps);
  IF v_ok <> array_length(v_emps, 1) THEN PERFORM factory.err('BUSINESS_RULE', 'أحد الموظفين ليس عضواً فعّالاً في القسم المحدد'); END IF;
  FOREACH e IN ARRAY v_emps LOOP
    INSERT INTO factory.work_assignments (order_line_id, lot_id, department_id, employee_id, assigned_qty, notes, assigned_by)
    VALUES (v_line, v_lot, v_dept, e, v_qty, v_notes, a.employee_id) RETURNING id INTO v_id;
    v_ids := v_ids || v_id;
  END LOOP;
  PERFORM factory.audit(a.employee_id, 'assignment.create', 'order_line', v_line::text, NULL,
    jsonb_build_object('employees', v_emps, 'quantity', v_qty, 'shared', array_length(v_emps, 1) > 1));
  RETURN jsonb_build_object('ids', to_jsonb(v_ids));
END $$;

CREATE OR REPLACE FUNCTION public.app_update_assignment(p_id uuid, p jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  a factory.actor_t := factory.require_actor(true);
  v_done int := factory.j_int(p, 'completedQty', 0, 1000000, 'الكمية المنجزة');
  v_status text := factory.j_text(p, 'status', 1, 20, true, 'الحالة');
  v_manager boolean := factory.has_role(a, 'SUPERVISOR') OR factory.has_role(a, 'ADMIN');
  w record;
BEGIN
  IF v_status NOT IN ('ASSIGNED', 'IN_PROGRESS', 'DONE', 'CANCELLED') THEN PERFORM factory.err('INVALID', 'حالة غير صالحة'); END IF;
  SELECT * INTO w FROM factory.work_assignments WHERE id = p_id FOR UPDATE;
  IF w.id IS NULL THEN PERFORM factory.err('NOT_FOUND', 'المهمة غير موجودة'); END IF;
  PERFORM factory.assert(w.employee_id = a.employee_id OR v_manager OR w.assigned_by = a.employee_id,
    'لا يمكنك تعديل مهمة موظف آخر');
  IF v_status = 'CANCELLED' AND w.employee_id = a.employee_id AND NOT v_manager THEN
    PERFORM factory.err('BUSINESS_RULE', 'إلغاء المهمة من صلاحية المشرف أو المدير');
  END IF;
  IF v_done > w.assigned_qty THEN PERFORM factory.err('BUSINESS_RULE', 'الكمية المنجزة أكبر من الكمية المسندة'); END IF;
  UPDATE factory.work_assignments SET completed_qty = v_done, status = v_status::factory.assignment_status, updated_at = now() WHERE id = p_id;
  PERFORM factory.audit(a.employee_id, 'assignment.progress', 'work_assignment', p_id::text, NULL,
    jsonb_build_object('before', jsonb_build_object('completed', w.completed_qty, 'status', w.status), 'after', p));
  RETURN jsonb_build_object('ok', true);
END $$;

CREATE OR REPLACE FUNCTION public.app_work_view() RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  a factory.actor_t := factory.require_actor(false);
  v_manager boolean := factory.has_role(a, 'SUPERVISOR') OR factory.has_role(a, 'ADMIN');
  v_assigner boolean := v_manager OR factory.in_stage(a, 'CUTTING');
BEGIN
  RETURN jsonb_build_object(
    'assigner', v_assigner, 'can_cancel', v_manager,
    'mine', (SELECT coalesce(jsonb_agg(x ORDER BY x->>'status', x->>'created_at' DESC), '[]'::jsonb) FROM (
        SELECT jsonb_build_object('id', w.id, 'order_code', o.order_code, 'color', ol.color, 'size', ol.size, 'lot_code', l.lot_code,
          'department_name', d.name_ar, 'assigned_qty', w.assigned_qty, 'completed_qty', w.completed_qty, 'status', w.status,
          'notes', w.notes, 'created_at', w.created_at,
          'co_workers', (SELECT count(*) - 1 FROM factory.work_assignments z WHERE z.order_line_id = w.order_line_id
                          AND z.lot_id IS NOT DISTINCT FROM w.lot_id AND z.department_id = w.department_id AND z.status <> 'CANCELLED')) AS x
          FROM factory.work_assignments w JOIN factory.order_lines ol ON ol.id = w.order_line_id JOIN factory.orders o ON o.id = ol.order_id
          LEFT JOIN factory.cut_lots l ON l.id = w.lot_id JOIN factory.departments d ON d.id = w.department_id
         WHERE w.employee_id = a.employee_id ORDER BY w.created_at DESC LIMIT 100) q),
    'open', CASE WHEN v_assigner THEN (SELECT coalesce(jsonb_agg(x), '[]'::jsonb) FROM (
        SELECT jsonb_build_object('id', w.id, 'employee_id', e.id, 'employee_name', e.display_name, 'department_name', d.name_ar,
          'order_code', o.order_code, 'color', ol.color, 'size', ol.size, 'assigned_qty', w.assigned_qty,
          'completed_qty', w.completed_qty, 'status', w.status) AS x
          FROM factory.work_assignments w JOIN factory.employees e ON e.id = w.employee_id JOIN factory.departments d ON d.id = w.department_id
          JOIN factory.order_lines ol ON ol.id = w.order_line_id JOIN factory.orders o ON o.id = ol.order_id
         WHERE w.status IN ('ASSIGNED', 'IN_PROGRESS') ORDER BY w.created_at DESC LIMIT 200) q) END,
    'lines', CASE WHEN v_assigner THEN (SELECT coalesce(jsonb_agg(jsonb_build_object('id', ol.id,
          'label', o.order_code || ' — ' || ol.color || ' / ' || ol.size || ' (' || ol.planned_qty || ')',
          'lots', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', l.id, 'code', l.lot_code) ORDER BY l.created_at), '[]'::jsonb)
                     FROM factory.cut_lots l WHERE l.order_line_id = ol.id)) ORDER BY o.due_date, o.order_code), '[]'::jsonb)
        FROM factory.order_lines ol JOIN factory.orders o ON o.id = ol.order_id WHERE o.status = 'RELEASED') END,
    'depts', CASE WHEN v_assigner THEN (SELECT coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'name', d.name_ar,
          'members', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'name', e.display_name) ORDER BY e.display_name), '[]'::jsonb)
                        FROM factory.employee_roles r JOIN factory.employees e ON e.id = r.employee_id
                       WHERE r.department_id = d.id AND r.role = 'WORKER' AND r.active AND e.active))
          ORDER BY factory.stage_rank(d.stage)), '[]'::jsonb)
        FROM factory.departments d WHERE d.active AND d.stage IS NOT NULL) END);
END $$;

-- ---------------------------------------------------------------- admin screen: onboarding status and open tasks
CREATE OR REPLACE FUNCTION public.app_admin_view() RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE a factory.actor_t := factory.require_actor(false);
BEGIN
  PERFORM factory.assert(factory.has_role(a, 'ADMIN'));
  RETURN jsonb_build_object(
    'self_id', a.employee_id,
    'employees', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'username', e.username, 'display_name', e.display_name,
        'active', e.active, 'must_change_password', e.must_change_password,
        'temp_expires_at', CASE WHEN e.must_change_password THEN e.temp_password_expires_at END,
        'temp_expired', e.must_change_password AND e.temp_password_expires_at < now(),
        'open_tasks', (SELECT count(*) FROM factory.work_assignments w WHERE w.employee_id = e.id AND w.status IN ('ASSIGNED', 'IN_PROGRESS')),
        'roles', (SELECT coalesce(jsonb_agg(jsonb_build_object('role', r.role, 'department_id', r.department_id, 'department_name', d.name_ar)
                    ORDER BY r.role, d.code), '[]'::jsonb)
                    FROM factory.employee_roles r LEFT JOIN factory.departments d ON d.id = r.department_id
                   WHERE r.employee_id = e.id AND r.active)) ORDER BY e.active DESC, e.display_name), '[]'::jsonb)
      FROM factory.employees e),
    'departments', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'code', d.code, 'name_ar', d.name_ar, 'stage', d.stage,
        'custody_mode', d.custody_mode, 'active', d.active,
        'member_count', (SELECT count(*) FROM factory.employee_roles r JOIN factory.employees e ON e.id = r.employee_id
                          WHERE r.department_id = d.id AND r.active AND e.active)) ORDER BY factory.stage_rank(d.stage) NULLS LAST, d.code), '[]'::jsonb)
      FROM factory.departments d));
END $$;

-- CREATE OR REPLACE keeps existing grants; re-assert them anyway (defence in depth).
REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA factory FROM PUBLIC;
DO $$
DECLARE f record; has_roles boolean := EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated');
BEGIN
  FOR f IN
    SELECT p.oid::regprocedure AS sig, p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = 'public' AND (p.proname LIKE 'app\_%' OR p.proname LIKE 'svc\_%')
  LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC', f.sig);
    IF has_roles THEN
      EXECUTE format('REVOKE ALL ON FUNCTION %s FROM anon, authenticated', f.sig);
      IF f.proname LIKE 'app\_%' THEN
        EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated', f.sig);
      ELSE
        EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role', f.sig);
      END IF;
    END IF;
  END LOOP;
END $$;
